package com.progressly.activity.api; import com.progressly.activity.domain.Task; import jakarta.validation.Valid; import java.util.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/tasks") public class TaskController{final TaskService service; public TaskController(TaskService s){service=s;} UUID u(Authentication a){return UUID.fromString(a.getName());} @PostMapping @ResponseStatus(HttpStatus.CREATED) public TaskDtos.Response create(Authentication a,@Valid @RequestBody TaskDtos.Request r){return service.create(u(a),r);} @GetMapping public Page<TaskDtos.Response> list(Authentication a,Pageable p){return service.list(u(a),p);} @GetMapping("/{id}") public TaskDtos.Response get(Authentication a,@PathVariable UUID id){return service.get(u(a),id);} @PutMapping("/{id}") public TaskDtos.Response update(Authentication a,@PathVariable UUID id,@Valid @RequestBody TaskDtos.Request r){return service.update(u(a),id,r);} @PatchMapping("/{id}/status") public TaskDtos.Response status(Authentication a,@PathVariable UUID id,@Valid @RequestBody TaskDtos.StatusRequest r){return service.status(u(a),id,r.status());} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(Authentication a,@PathVariable UUID id){service.delete(u(a),id);}}
